import{z as A,x as B,o as t,c as p,q as o,j as l,D as E,d as r,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"工件台加速度与产能","description":"","frontmatter":{"title":"工件台加速度与产能","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/stage-acceleration-throughput.md","filePath":"litho/stage-acceleration-throughput.md","lastUpdated":1791063341000}'),d={name:"litho/stage-acceleration-throughput.md"};function h(u,a,m,D,c,f){const i=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="工件台加速度与产能" tabindex="-1">工件台加速度与产能 <a class="header-anchor" href="#工件台加速度与产能" aria-label="Permalink to &quot;工件台加速度与产能&quot;">​</a></h1><div class="epigraph"><p>扫描产能不是激光有多亮，常是台能加多快、转向多重而不把套刻抖坏。加速度进会计，也进伺服残差。</p><footer>—— 据 ASML, TWINSCAN: 20 years of lithography innovation（公开故事，2021）与 ASML 产能公开资料整理</footer></div><p><a href="/litho/vibration-isolation">上一课</a>挡住地。缺口是台自己：扫描段匀速，场间加速、转向、对准。本课钉加速度与产能，同步误差下一课 MSD。<a href="/litho/scanner-throughput">扫描仪产能</a>课给过产能公式骨架，本课拆最大的一块软肉：场间死时间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>吞吐公式里有加速时间。加速度大，死时间短，但力大、液膜难、隔振被打。只升激光 \\(f\\)，台加不上速，产能不动。</p><p>展开：一片的工时是每场曝光、每场开销（步进、整定）与每片开销（装载、预对准）之和。场间死时间是其中最大也最可优化的一段：加速度大则步进短，但力大、液膜难、隔振被打——省的时间可能被更长的整定吃回去。「只升激光 rep rate、台加不上速」的教训很常见：光源升级前，先看死时间占多少。</p><p><span class="marginnote">「整定」（settling）翻译成开车的话：猛打方向盘之后车还在左右晃，你得等它稳下来才能对准车道线。工件台同理——加速结束时台子还在微振，必须等振幅衰减到几纳米以内才能开始曝光，这段等待就是整定时间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运动规划：扫描速度、加速极限、急动度 jerk 限制。双台：一块曝光一块对准，掩盖加速。浸没头对加速度有流体上限。会计：把加速段从「曝光时间」里分开报，否则优化激光会失望。</p><p>工程流程：把每场拆成扫描段与步进段——扫描段要匀速段的平直，步进段用 jerk 受限的 S 曲线，在峰值加速度、峰值速度与行程间优化；扫描方向逐场交替，换向 turnaround 的残振要压到下一场开曝前。双台（<a href="/litho/twinscan-dual-stage">Twinscan</a>）一台曝光、另一台并行对准与换片，把步进与装载从关键路径拿掉。浸没另有一条流体上限：水膜跟随加速度有限，剪切太狠会撕开液膜，上限由「液膜不破」决定。</p>',10)),(t(),l(s,null,{default:E(()=>[n(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8A%A0%E9%80%9F%E5%BA%A6%E4%B8%8A%E9%99%90%22%5D%20--%3E%20T%5B%22%E5%9C%BA%E9%97%B4%E6%AD%BB%E6%97%B6%E9%97%B4%22%5D%0A%20%20T%20--%3E%20WPH%5B%22%E7%89%87%2F%E5%B0%8F%E6%97%B6%22%5D%0A%20%20A%20--%3E%20F%5B%22%E5%8A%9B%20%2F%20%E6%B6%B2%E8%86%9C%22%5D%0A%20%20F%20--%3E%20OVL%5B%22%E5%A5%97%E5%88%BB%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"死时间按场数放大：约百场的一片，每场 10 ms 开销到片尾就是一秒上下，在 200 wph 的账上占好几个百分点——常比光源微升级更值得先优化。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"牛顿定律：力 = 质量 × 加速度。台+片+夹盘质量固定，加速度直接是对导轨与隔振的力。液膜在转向时剪切，缺陷与同步误差一起升。",-1)),a[6]||(a[6]=e("p",null,"写透一点：台、片、卡盘加浸没液的质量固定，加速度直接是导轨、电机与隔振的力。真正卡产能的常是 jerk：加速度突变激起机架与隔振的模态，残振要衰减到套刻允许的水平才能开曝——「加速度调高、整定拉长」的净收益可能为负，账上死时间不降反升。套刻与产能抢同一条预算：残振进曝光段就是同步误差，液膜转向剪切还叠加缺陷。失配形状可辨：残振型套刻误差在换向两场成对反号，不是对准或网格的病。",-1)),(t(),l(s,null,{default:E(()=>[n(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E8%B0%83%E9%AB%98%E5%8A%A0%E9%80%9F%E5%BA%A6%E4%B8%8A%E9%99%90%22%5D%20--%3E%20SAVE%5B%22%E6%AD%A5%E8%BF%9B%E6%AE%B5%E7%BC%A9%E7%9F%AD%20%E7%9C%81%E6%97%B6%E9%97%B4%22%5D%0A%20%20UP%20--%3E%20JERK%5B%22%E5%8A%A0%E9%80%9F%E5%BA%A6%E7%AA%81%E5%8F%98%20jerk%20%E5%8F%98%E5%A4%A7%22%5D%0A%20%20JERK%20--%3E%20MODE%5B%22%E6%BF%80%E8%B5%B7%E6%9C%BA%E6%9E%B6%E4%B8%8E%E9%9A%94%E6%8C%AF%E6%A8%A1%E6%80%81%22%5D%0A%20%20MODE%20--%3E%20SET%5B%22%E6%95%B4%E5%AE%9A%E6%97%B6%E9%97%B4%E5%8F%98%E9%95%BF%22%5D%0A%20%20SET%20--%3E%20NET%5B%22%E5%87%80%E6%94%B6%E7%9B%8A%E5%8F%AF%E8%83%BD%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20SAVE%20--%3E%20NET%0A%20%20MODE%20--%3E%20LEAK%5B%22%E6%AE%8B%E6%8C%AF%E6%BC%8F%E8%BF%9B%E6%9B%9D%E5%85%89%E6%AE%B5%22%5D%0A%20%20LEAK%20--%3E%20MSD%5B%22%E6%88%90%E5%AF%B9%E5%8F%8D%E5%8F%B7%E7%9A%84%E5%A5%97%E5%88%BB%E8%AF%AF%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">jerk 就是加速度的变化率，好比「踩刹车踩得多急」：匀速踩下去乘客没感觉，一脚跺死全车前倾。台子对这种突变最敏感——加速度曲线越平滑（S 曲线），激起的机架振动越小。</span></p><p><span class="marginnote">数字实例：设台、片、卡盘合计约 100 kg，加速度 \\(5\\ \\mathrm{m/s^2}\\)，由 \\(F = m \\times a\\)，导轨与电机要持续出约 500 N 的力——相当于挂着两个成年人在做高频往复运动，还要把位置控在几纳米内。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只算时间与力，不写扫描中双台的同步误差怎么测（MSD 下一课）；柔性模态与地基的耦合归 <a href="/litho/vibration-isolation">振动隔离</a>课，浸没流体归浸没课。运动学假设刚性台：jerk 激起的模态一旦闯进曝光段，规划要让位给隔振与整定策略。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>产能会计必须单列加速死时间。</li><li>加速度与套刻、浸没流体抢同一条力预算。</li><li>下一课 MSD：加速度规划得再漂亮，扫描中两台跟不齐仍糊。</li><li>出处：扫描仪产能课；Twinscan。</li></ul>',6))])}const g=A(d,[["render",h]]);export{T as __pageData,g as default};
